package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app;
import org.springframework.kafka.config.KafkaListenerEndpointRegistry; import org.springframework.kafka.listener.MessageListenerContainer; import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.consumer.*;
public class TakeoverConsumerControl {private final KafkaListenerEndpointRegistry registry;public TakeoverConsumerControl(KafkaListenerEndpointRegistry registry){this.registry=registry;}public void startBoth(){container(TakeoverConsumerA.ID).start();container(TakeoverConsumerB.ID).start();}public void stop(String consumer){container(TakeoverConsumerA.LABEL.equals(consumer)?TakeoverConsumerA.ID:TakeoverConsumerB.ID).stop();}private MessageListenerContainer container(String id){MessageListenerContainer c=registry.getListenerContainer(id);if(c==null)throw new IllegalStateException("Listener not found: "+id);return c;}}
